import java.util.List;
import java.util.stream.Collectors;

public class Demo {
    public static void main(String[] args) {
        List<String> mots = List.of("chat", "chien", "rat", "cheval");

        // Source : mots.stream()
        // Opérations intermédiaires : filter puis map
        // Opération terminale : collect
        List<String> resultat = mots.stream()
                .filter(m -> m.length() > 3)      // garde les mots de plus de 3 lettres
                .map(m -> m.toUpperCase())        // transforme chacun en majuscules
                .collect(Collectors.toList());    // rassemble le tout dans une liste

        System.out.println(resultat); // [CHIEN, CHEVAL]
    }
}

import java.util.List;
import java.util.stream.Collectors;

public class Demo {
    public static void main(String[] args) {
        List<String> mots = List.of("chat", "chien", "cheval");

        // Ancienne façon : collecteur explicite + import de Collectors.
        List<String> ancienne = mots.stream()
                .map(String::toUpperCase)
                .collect(Collectors.toList());

        // Depuis Java 16 : plus concis, sans collecteur ni import de Collectors.
        List<String> moderne = mots.stream()
                .map(String::toUpperCase)
                .toList();

        System.out.println(ancienne); // [CHAT, CHIEN, CHEVAL]
        System.out.println(moderne);  // [CHAT, CHIEN, CHEVAL]
    }
}

import java.util.ArrayList;
import java.util.List;

public class Demo {
    public static void main(String[] args) {
        List<Integer> figee = List.of(1, 2, 3).stream()
                .map(n -> n * 2)
                .toList();

        System.out.println(figee); // [2, 4, 6] : lecture, aucun probleme

        // figee.add(8); // leverait UnsupportedOperationException : liste NON modifiable

        // Si on a besoin d'ajouter, on recopie dans une liste modifiable.
        List<Integer> modifiable = new ArrayList<>(figee);
        modifiable.add(8);
        System.out.println(modifiable); // [2, 4, 6, 8]
    }
}

import java.util.List;

public class Demo {
    record Commande(String client, List<String> articles) { }

    public static void main(String[] args) {
        List<Commande> commandes = List.of(
            new Commande("Ana", List.of("stylo", "cahier")),
            new Commande("Bob", List.of("gomme"))
        );

        // Version flatMap : chaque commande renvoie un stream de ses articles.
        List<String> avecFlatMap = commandes.stream()
                .flatMap(c -> c.articles().stream())
                .toList();

        // Version mapMulti : on pousse chaque article dans le consommateur "push".
        List<String> avecMapMulti = commandes.stream()
                .<String>mapMulti((c, push) -> {
                    for (String article : c.articles()) {
                        push.accept(article); // depose un element dans le flux
                    }
                })
                .toList();

        System.out.println(avecFlatMap);  // [stylo, cahier, gomme]
        System.out.println(avecMapMulti); // [stylo, cahier, gomme]
    }
}

import java.util.List;

public class Demo {
    public static void main(String[] args) {
        List<Integer> nombres = List.of(1, 2, 3, 4);

        // Pour chaque nombre pair, on pousse le nombre ET son double.
        // Les nombres impairs ne poussent rien (zero sortie).
        List<Integer> resultat = nombres.stream()
                .<Integer>mapMulti((n, push) -> {
                    if (n % 2 == 0) {
                        push.accept(n);       // le nombre lui meme
                        push.accept(n * 2);   // et son double
                    }
                })
                .toList();

        System.out.println(resultat); // [2, 4, 4, 8]
    }
}

