import java.util.List;
import java.util.stream.Collectors;

public class Demo {
    public static void main(String[] args) {
        List<Integer> notes = List.of(12, 15, 9, 18);

        double moyenne = notes.stream()
                .collect(Collectors.teeing(
                        Collectors.summingDouble(n -> n), // 1er collecteur : la somme
                        Collectors.counting(),            // 2e collecteur : le compte
                        (somme, compte) -> somme / compte // fusion : somme / compte
                ));

        System.out.println(moyenne); // 13.5
    }
}

